	);
	const ticks: number[] = [];
	for (let v = Math.ceil(lo / step) * step; v <= hi + 1e-9; v += step) {
		ticks.push(Number(v.toFixed(10)));
	}
	return ticks;
}

/** UTC date as dotted YYYY.MM.DD so a day "01" never reads as a January tick. */
export function dateLabel(ts: number): string {
	const d = new Date(ts);
