/** Round axis ticks inside [min, max] (padded to include zero), about five of them. */
export function niceTicks(min: number, max: number): number[] {
	const lo = Math.min(min, 0);
	const hi = Math.max(max, 0);
	const span = hi - lo;
	if (!Number.isFinite(span) || span <= 0) return [0];
	const raw = span / 5;
	const mag = 10 ** Math.floor(Math.log10(raw));
	const candidates = [1, 2, 5, 10].map((m) => m * mag);
	const step = candidates.reduce((best, c) =>
		Math.abs(Math.log(c / raw)) < Math.abs(Math.log(best / raw)) ? c : best,
	);
	const ticks: number[] = [];
	for (let v = Math.ceil(lo / step) * step; v <= hi + 1e-9; v += step) {
		ticks.push(Number(v.toFixed(10)));
	}
	return ticks;
}

