/** Round axis ticks inside [min, max] (padded to include zero), about five of them. */
export function niceTicks(min: number, max: number): number[] {
	const lo = Math.min(min, 0);
	const hi = Math.max(max, 0);
	const span = hi - lo;
	if (!Number.isFinite(span) || span <= 0) return [0];
	const raw = span / 5;
	const mag = 10 ** Math.floor(Math.log10(raw));
	const candidates = [1, 2, 5, 10].map((m) => m * mag);
	const step = candidates.reduce((best, c) =>
		Math.abs(Math.log(c / raw)) < Math.abs(Math.log(best / raw)) ? c : best,
	);
	const ticks: number[] = [];
	for (let v = Math.ceil(lo / step) * step; v <= hi + 1e-9; v += step) {
		ticks.push(Number(v.toFixed(10)));
	}
	return ticks;
}

/** UTC date as dotted YYYY.MM.DD so a day "01" never reads as a January tick. */
export function dateLabel(ts: number): string {
	const d = new Date(ts);
	const mm = String(d.getUTCMonth() + 1).padStart(2, "0");
	const dd = String(d.getUTCDate()).padStart(2, "0");
	return `${d.getUTCFullYear()}.${mm}.${dd}`;
}

export interface CurveView {
	t: number[];
	rule: number[];
	hold: number[];
	ticks: number[];
	labels: string[];
}

/** Cumulative-fraction curve in percent; a missing point carries the previous value over. */
export function curveView(trial?: ScreenTrial | null): CurveView | null {
	const curve = trial?.curve;
	if (!curve || curve.t.length < 2) return null;
	const convert = (series: (number | null)[]) => {
		let last = 0;
		return series.map((v) => (v == null ? last : (last = v * 100)));
	};
	const rule = convert(curve.rule);
	const hold = convert(curve.hold);
	const all = [...rule, ...hold];
	return {
		t: curve.t,
		rule,
		hold,
		ticks: niceTicks(Math.min(...all), Math.max(...all)),
		labels: curve.t.map(dateLabel),
	};
}

/** The trial at horizon `h`, falling back to the lead trial when the feature lacks it. */
export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
	if (h === "lead") return leadTrial(f);
	return f.trials.find((t) => t.h === h) ?? leadTrial(f);
}

export interface ScreenRuleTile {
	id: string;
	group: string;
	name: string;
	label: string;
	tip: string;
}

/** The screen's trade rule as tiles: direction, indicator, cost, holding period (plus a regime gate). */
export function screenRule(doc: ScreenDoc, f: ScreenFeature, trial: ScreenTrial): ScreenRuleTile[] {
	const fixed = doc.fixed_sign;
	const sign = fixed ?? trial.train_sign;
	const long = sign >= 0;
	const signChanged =
		fixed == null && new Set(trial.folds.map((fold) => Math.sign(fold.train_sign))).size > 1;
	const direction: ScreenRuleTile = {
		id: "direction",
		group: "entry",
		name: long ? "기준 위면 롱" : "기준 위면 숏",
		label: signChanged ? "부호 바뀜" : long ? "순방향" : "역추세",
		tip:
			fixed != null
				? `방향 부호가 ${fixed > 0 ? `+${fixed}` : fixed}로 고정되어 있다. 지표가 기준(0) 위면 ${long ? "롱" : "숏"}으로 들어간다.`
				: signChanged
					? "학습 연도마다 방향 부호가 다르다. 연도마다 부호가 바뀌었다."
					: `학습 구간에서 정한 방향 부호 ${sign > 0 ? `+${sign}` : sign}다. 지표가 기준(0) 위면 ${long ? "롱" : "숏"}으로 들어간다.`,
	};
	const indicator: ScreenRuleTile = {
		id: "indicator",
		group: "entry",
		name: featureName(f),
		label: f.tradeable === false ? "참고 지표" : "거래 지표",
		tip: featureDef(f) || f.feature,
	};
	const tiles: ScreenRuleTile[] = [direction, indicator];
	if (doc.regime === "down") {
		tiles.push({
			id: "regime",
			group: "entry",
			name: "200일 평균 아래만",
			label: "국면 게이트",
			tip: "종가가 200일 평균 아래인 날(하락 국면)에만 점수를 매기고 매매한다.",
		});
	}
	tiles.push(
		{
			id: "fill",
			group: "fill",
			name: `편도 ${Math.round(doc.cost_per_side * 1e4)}bp`,
			label: "체결 비용",
			tip: `한 번 사고팔 때마다 편도 ${(doc.cost_per_side * 1e4).toFixed(0)}bp를 비용으로 뺀다.`,
		},
		{
			id: "hold",
			group: "exit",
			name: `${trial.h}${doc.unit} 보유`,
			label: "보유 기간",
			tip: `진입 후 ${trial.h}${doc.unit} 동안 들고 시계가 끝나면 청산한다.`,
		},
	);
	return tiles;
}
